function m=gimbal_sample(g,neutral,c)
% Encoder snapshot; covariance uses CAMERA-local right rotation errors.
r=g.angles(1); p=g.angles(2); y=g.angles(3);
R=[cos(y) -sin(y) 0;sin(y) cos(y) 0;0 0 1]* ...
  [cos(p) 0 sin(p);0 1 0;-sin(p) 0 cos(p)]* ...
  [1 0 0;0 cos(r) -sin(r);0 sin(r) cos(r)];
E=[1 0 -sin(p);0 cos(r) sin(r)*cos(p);0 -sin(r) cos(r)*cos(p)];
sigma=c.encoder_std_rad*double(c.enabled);
m=struct('timestamp',g.timestamp, ...
    'T_body_camera',[R*neutral(1:3,1:3) neutral(1:3,4);0 0 0 1], ...
    'angular_velocity_camera',(neutral(1:3,1:3)'*E*g.rates)', ...
    'covariance',eye(3)*sigma^2,'valid',true,'saturated',logical(g.saturated));
end
